function cookie(e){let t=()=>{let t=decodeURIComponent(document.cookie).split(";");for(let o in t){let i=t[o].trim().split("=");if(i[0]===e)return i.slice(1).join("=")}},o=(t,o=NaN)=>(e=>document.cookie=e)(e+"="+t+";path=/"+(isNaN(o)?"":";expires="+new Date(Date.now()+1e3*o).toUTCString()));return{value:t,set:o,delete:()=>o("",0),toString:t}}